agent-browser --session tab4 eval --stdin <<'EOF'
const form = document.querySelector('main') || document.body;
const els = Array.from(form.querySelectorAll('input,select,textarea,button,label'));
els.map(e => ({tag: e.tagName, type: e.type, name: e.name, id: e.id, placeholder: e.placeholder, ariaLabel: e.getAttribute('aria-label'), value: e.value, text: (e.tagName==='SELECT'? Array.from(e.options).map(o=>o.textContent).join('|') : (e.textContent||'').slice(0,40))}));
EOF
